using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;
public static class StudioPickingCacheValidation {
 public static void Run(){int exit=0;try{Validate();}catch(Exception e){exit=1;Debug.LogException(e);}EditorApplication.Exit(exit);}

 const BindingFlags F=BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static;
 public static void Validate(){int checks=0;void Check(bool ok,string message){if(!ok)throw new Exception(message);checks++;}var mesh=new Mesh();mesh.vertices=new[]{new Vector3(-1,-1,0),new Vector3(1,-1,0),new Vector3(0,1,0)};mesh.triangles=new[]{0,1,2};mesh.RecalculateBounds();var doc=ScriptableObject.CreateInstance<StudioModelDocument>();doc.nodes.Add(new StudioModelDocument.Node{name="one",mesh=mesh});doc.nodes.Add(new StudioModelDocument.Node{name="two",mesh=mesh,position=Vector3.right*10});
 try{using(var editor=new StudioModelEditor(()=>{})){editor.Load(doc);var et=typeof(StudioModelEditor);var capture=et.GetMethod("CaptureOccluders",F);var query=et.GetMethods(F).Single(m=>m.Name=="Occluded"&&m.IsStatic);var type=et.GetNestedType("OcclusionMesh",F);var tree=type.GetField("Tree",F);var ray=new Ray(Vector3.back*2,Vector3.forward);Array Capture()=>(Array)capture.Invoke(editor,null);bool Query(Array entries)=>(bool)query.Invoke(null,new object[]{ray,3f,entries});
 var first=Capture();Check(Query(first),"First query hits source");var original=tree.GetValue(first.GetValue(0));Check(original!=null,"First intersected mesh builds index");var warm=Capture();Check(ReferenceEquals(original,tree.GetValue(warm.GetValue(0))),"Later selection reuses mesh index");Check(ReferenceEquals(original,tree.GetValue(warm.GetValue(1))),"Transformed instances share local index");
 mesh.vertices=mesh.vertices.Select(v=>v+Vector3.right*20).ToArray();mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);var edited=Capture();Check(tree.GetValue(edited.GetValue(0))==null,"Geometry dirty version invalidates index");Check(!Query(edited),"Edited geometry has current bounds and visibility");editor.Transforms[0].position=Vector3.left*20;var transformed=Capture();Check(Query(transformed),"Transform changes map rays against edited geometry");var updated=tree.GetValue(transformed.GetValue(0));Check(updated!=null&&!ReferenceEquals(original,updated),"Edited geometry builds replacement index");editor.Transforms[0].position=Vector3.left*21;var moved=Capture();Check(ReferenceEquals(updated,tree.GetValue(moved.GetValue(0))),"Transform-only edits reuse local geometry index");editor.Transforms[0].gameObject.SetActive(false);Check(!Query(Capture()),"Hidden mesh no longer occludes selection");editor.Load(doc);Check(((IDictionary)et.GetField("occlusionIndices",F).GetValue(editor)).Count==0,"Rebuild releases geometry indices");}
 var empty=new VDPrecisionBaker.RayIndex(Array.Empty<Vector3>(),Array.Empty<int>());Check(!empty.Occluded(Vector3.zero,Vector3.forward,10),"Empty shared index is clear");var vertices=Enumerable.Repeat(new[]{new Vector3(-1,-1,0),new Vector3(1,-1,0),new Vector3(0,1,0)},100).SelectMany(v=>v).ToArray();var equal=new VDPrecisionBaker.RayIndex(vertices,Enumerable.Range(0,vertices.Length).ToArray());Check(equal.Occluded(Vector3.back,Vector3.forward,2),"Duplicate-centroid median partition terminates and hits");
 File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../picking-cache-validation.txt")),"PASS "+checks+" persistent index assertions");}finally{UnityEngine.Object.DestroyImmediate(mesh);UnityEngine.Object.DestroyImmediate(doc);}}
}
